    fix: "val ks = KeyStore.getInstance(\"AndroidKeyStore\").apply { load(null) }\nif (!ks.containsAlias(\"data_key\")) {\n    val kg = KeyGenerator.getInstance(\"AES\", \"AndroidKeyStore\")\n    kg.init(spec(\"data_key\"))\n    kg.generateKey()\n}\nval key = ks.getKey(\"data_key\", null)",
